<?php
require __DIR__.'/bootstrap.php';$u=require_user();$uid=(int)$u['id'];
if(method()==='GET'){$stmt=$db->prepare('SELECT * FROM wallets WHERE user_id=?');$stmt->bind_param('i',$uid);$wallet=db_one($stmt);$stmt=$db->prepare('SELECT wt.* FROM wallet_transactions wt JOIN wallets w ON w.id=wt.wallet_id WHERE w.user_id=? ORDER BY wt.created_at DESC LIMIT 50');$stmt->bind_param('i',$uid);$wallet['transactions']=db_all($stmt);ok($wallet);}
if(method()==='POST'&&($_GET['action']??'')==='withdraw'){$in=input();$amount=(float)($in['amount']??0);if($amount<=0)fail('Enter a valid withdrawal amount.',422);$db->begin_transaction();try{$fee=(float)($db->query("SELECT setting_value FROM system_settings WHERE setting_key='withdrawal_fee'")->fetch_assoc()['setting_value']??0);$total=$amount+$fee;$stmt=$db->prepare('SELECT id,available_balance FROM wallets WHERE user_id=? FOR UPDATE');$stmt->bind_param('i',$uid);$w=db_one($stmt);if(!$w||$total>(float)$w['available_balance'])fail('Insufficient wallet balance including the $'.number_format($fee,2).' withdrawal fee.',409);$stmt=$db->prepare('UPDATE wallets SET available_balance=available_balance-? WHERE id=?');$stmt->bind_param('di',$total,$w['id']);$stmt->execute();$negative=-$amount;$ref='WD-'.strtoupper(bin2hex(random_bytes(4)));$stmt=$db->prepare("INSERT INTO wallet_transactions(wallet_id,type,amount,status,reference,description) VALUES(?,'withdrawal',?,'pending',?,'Withdrawal to dummy account')");$stmt->bind_param('ids',$w['id'],$negative,$ref);$stmt->execute();if($fee>0){$feeAmount=-$fee;$stmt=$db->prepare("INSERT INTO wallet_transactions(wallet_id,type,amount,status,reference,description) VALUES(?,'commission',?,'completed',?,'Withdrawal fee')");$stmt->bind_param('ids',$w['id'],$feeAmount,$ref);$stmt->execute();}$db->commit();ok(['reference'=>$ref,'amount'=>$amount,'fee'=>$fee,'total_deducted'=>$total],'Withdrawal request submitted.',201);}catch(Throwable $e){$db->rollback();throw $e;}}fail('Method not allowed.',405);
